from menu import price_of


class Cart:
    MAX_QTY = 20

    def __init__(self):
        self._items = {}          # item -> quantity

    def add(self, item, qty):
        if price_of(item) is None:
            return f"error: unknown item {item}"
        if not 1 <= qty <= self.MAX_QTY:
            return "error: quantity must be 1-20"
        if self._items.get(item, 0) + qty > self.MAX_QTY:
            return f"error: at most 20 {item} per order"
        self._items[item] = self._items.get(item, 0) + qty
        return f"added {qty} {item}"

    def remove(self, item, qty):
        have = self._items.get(item, 0)
        if have == 0:
            return f"error: {item} not in cart"
        if qty >= have:
            del self._items[item]
            return f"removed all {item}"
        self._items[item] = have - qty
        return f"removed {qty} {item}"

    def lines(self):
        return [f"{item} x{qty} = {qty * price_of(item)}" for item, qty in sorted(self._items.items())]

    def total(self):
        subtotal = sum(qty * price_of(item) for item, qty in self._items.items())
        saved = subtotal // 10 if subtotal >= 200 else 0
        return subtotal - saved, saved
